function courseVoice(ref) {
 if (!ref) return null;
 const words=window.UNLOCK_WORD_PRONUNCIATION, glossary=window.UNLOCK_TASK_GLOSSARY_AUDIO;
 switch(ref.set){
  case "ryan-word":return words.entries[ref.key]?.audio;
  case "ryan-example":return words.examples[ref.key];
  case "alan-word":return glossary.words[ref.key];
  case "alan-example":return glossary.examples[ref.key];
  case "revised-example":return courseLexemeReviews[ref.key]?.clip;
  case "full":return (window.UNLOCK_COURSE_VOICE_EXTRA?.[ref.key]??window.UNLOCK_COURSE_VOICE?.[ref.key])?.clip;
  default:return null;
 }
}

function courseWordCard(word) {
 const controls=(kind,label,ref,tip)=>{
  const clip=courseVoice(ref);
  return clip?wordCardAudioHTML(kind,label,tip,clip):'<button type="button" class="flow-pronounce" disabled>'+label+'</button>';
 };
 const phonetics=word.wordVoice.ipa??window.UNLOCK_COURSE_IPA?.[word.wordVoice.key]??
  window.UNLOCK_COURSE_VOICE_EXTRA?.[word.wordVoice.key]?.ipa??window.UNLOCK_COURSE_VOICE?.[word.wordVoice.key]?.ipa;
 const example=esc(word.example);
 const hit=esc(word.exampleMark);
 const mark=hit&&example.indexOf(hit)>=0?example.replace(hit,'<strong>'+hit+'</strong>'):example;
 const picture=word.visual.src?flowVisualHTML(word.visual):
  word.themePhoto?'<figure class="course-word-theme">'+cropHTML(word.themePhoto)+'</figure>':
  '<div class="flow-visual" aria-hidden="true"></div>';
 return '<div class="flow-wordcards"><article data-flow-word="'+esc(word.id)+'"><div class="flow-card-copy" lang="en-GB">'+
  '<div class="flow-card-controls" role="group" aria-label="British English audio">'+
  controls("word","Word",word.wordVoice,"Play word pronunciation for "+word.term)+
  controls("example","Example",word.exampleVoice,"Play example sentence for "+word.term)+'</div>'+
  '<div class="flow-card-head"><h2>'+esc(word.term)+' <small>'+esc(word.pos)+'</small></h2></div>'+
  '<div class="flow-card-sound"><p class="flow-card-ipa">'+esc(phonetics??"")+'</p></div>'+
  '<p class="flow-card-definition">'+esc(word.definition)+'</p>'+
  (mark?'<p class="flow-card-example">'+mark+'</p>':"")+
  '<p class="flow-pronunciation-error" data-card-audio-error role="status" hidden></p></div>'+picture+'</article></div>';
}

function courseFlowHTML(c,p) {
 if (c.flow?.kind==="objectives-review") return courseObjectivesNativeHTML(c,p);
 if (c.classroomVideo) return courseVideoHTML(c);
 if (c.exerciseVocabulary) return '<div class="exercise-glossary">'+flowGlossaryHTML(c.exerciseVocabulary[p])+'</div>';
 if (c.flow.kind==="reading") return courseOriginalReadingHTML(c,c.flow.pages[p].sourcePage);
 if (c.courseOriginalOnly) return '<div class="course-picture-only">'+
  courseSourceImage(c.courseOriginalOnly[p]??c.courseOriginalOnly[0])+'</div>';
 if (c.flow.kind==="cards"&&c.flow.pages[p][0]?.wordVoice) return courseWordCard(c.flow.pages[p][0]);
 if (c.playback?.launchInline) return courseMediaPlayer(c.playback);
 return classroomFlowHTML(c,p);
}

function courseMediaPlayer(media) {
 const video=media.type==="video";
 const tag=video?"video":"audio";
 return '<div class="course-player'+(video?' course-video':'')+'"><'+tag+
  ' src="'+esc(media.src)+'" controls preload="none"'+(video?' playsinline':"")+
  ' aria-label="'+esc(media.title)+'"></'+tag+'>'+
  (media.captions?.length?'<p class="course-caption" data-course-caption aria-live="off"></p>':"")+'</div>';
}

function courseMaterialsHTML(c) {
 return c.courseMaterials.map(material=>{
  const originalOnly=material.kind==="reading"||material.kind==="referenced_page"||
   (material.kind==="material"&&/^READING [12]$/i.test(material.title));
  const parts=originalOnly?"":material.screens?.map((line,i)=>{
   const marked=material.markScreens?.[i];
   const html=marked?.length?courseMarkText(line,marked.map((part,index)=>({...part,index})),marked.map((_,index)=>index)):courseText(line);
   return '<p>'+html.replace(/(^|\n)#{1,5} ([^\n]+)/g,'$1<strong class="course-material-title">$2</strong>').replace(/\n/g,"<br>")+'</p>';
  }).join("")??"";
  const sources=material.sources.map(source=>{
   if (originalOnly&&source.page) return courseOriginalPageImage(courseOriginalPages.aliases[source.src]??courseOriginalKey(c,source.page),"教材第 "+source.page+" 页",true);
   return courseSourceImage(source,"材料原页");
  }).join("");
  return '<section class="course-material-block"><h3>'+esc(material.title)+'</h3>'+
   (parts?'<div class="course-material-copy">'+parts+'</div>':"")+sources+'</section>';
 }).join("");
}

function courseAnswerHTML(answer) {
 return '<div class="course-answer-copy">'+answer.split(/\n+/).map(line=>'<p>'+courseText(line)+'</p>').join("")+'</div>';
}

function coursePanels(c,p) {
 if (c.classroomVideo) return {rail:courseVideoButtons(c),panels:"",media:[]};
 if (!c.coursePages) return {rail:courseQuestionVideoButton(c),panels:"",media:[]};
 const buttons=[];
 const drawers=[];
 const control=(key,label,html)=>{
  buttons.push('<button type="button" data-course-open="'+key+'" aria-expanded="false">'+label+'</button>');
  drawers.push('<section class="classroom-drawer course-drawer" data-course-panel="'+key+'" hidden aria-label="'+label+'">'+
   '<header><h2>'+label+'</h2><button type="button" data-course-close>返回题目</button></header>'+
   '<div class="course-drawer-copy">'+html+'</div></section>');
 };
 const referenceAnswers=referenceIsInline(c)&&/data-course-(?:answer-target|correct-choice)/.test(courseTaskHTML(c,p));
  if (coursePageBlocks(c,p).some(courseHasPlacement)||referenceAnswers) {
  const revealLabel=esc(c.courseRevealLabel??"核对");
  buttons.push('<button type="button" data-course-reveal aria-pressed="false">'+revealLabel+'</button>');
 }
 if (c.courseMaterials.length) control("material","材料",courseMaterialsHTML(c));
 const answer=coursePublishedAnswers?.[c.id]?.rewriteKey??c.courseAnswer?.text;
 const answerPanel=answer?'<section class="course-inline-answer" id="course-inline-answer" hidden aria-label="答案" tabindex="0">'+
  courseAnswerHTML(answer)+'</section>':"";
 if(answerPanel)buttons.push('<button type="button" data-course-answer-toggle aria-controls="course-inline-answer" aria-expanded="false">答案</button>');
 buttons.push(courseQuestionVideoButton(c));
 const media=courseRemainingMedia(c);
 if (media.length) {
  const hasVideo=media.some(asset=>asset.type==="video");
  const hasOther=media.some(asset=>asset.type!=="video");
  const label=hasVideo?(hasOther?"音视频":"视频"):"录音";
  control("media",label,media.map(asset=>'<section class="course-media-entry"><h3>'+esc(asset.title)+'</h3>'+
   courseMediaPlayer(asset)+'</section>').join(""));
 }
 return {rail:buttons.join(""),panels:drawers.join("")+answerPanel,media};
}

function courseBindCaptions(player, config) {
 const caption=player.parentElement.querySelector("[data-course-caption]");
 if (!caption||!config?.captions?.length) return;
 const cue=()=>{
  const clock=player.currentTime;
  caption.textContent=config.captions.find(line=>line.start<=clock&&clock<line.end)?.text??"";
 };
 player.addEventListener("timeupdate",cue);
 player.addEventListener("seeked",cue);
}

function wireCourseTools(doc,c) {
 wireCourseOriginalPages(doc);
 if (wireCourseCinema(doc,c)) return;
 if (c.playback?.launchInline) {
  const player=doc.querySelector(".course-player video");
  if (player) courseBindCaptions(player,c.playback);
 }
 if (!c.coursePages) return;
 const controls=[...doc.querySelectorAll("[data-course-open]")];
 const panels=[...doc.querySelectorAll("[data-course-panel]")];
 const body=doc.querySelector(".slide-area");
 let opener;
 const close=()=>{
  for (const panel of panels) {
   panel.hidden=true;
   panel.querySelectorAll("audio,video").forEach(player=>player.pause());
  }
  for(const control of controls) control.setAttribute("aria-expanded","false");
 };
 for(const control of controls) {
  control.onclick=()=>{
   const panel=panels.find(node=>node.dataset.coursePanel===control.dataset.courseOpen);
   const show=panel.hidden;
   close();
   if(show) {
    panel.hidden=false;
    control.setAttribute("aria-expanded","true");
    opener=control;
    panel.querySelector("[data-course-close]").focus({preventScroll:true});
   }
  };
 }
 for(const panel of panels) panel.querySelector("[data-course-close]").onclick=()=>{
  close();
  opener?.focus({preventScroll:true});
 };
 doc.addEventListener("keydown",e=>{
  if(e.key==="Escape"&&panels.some(panel=>!panel.hidden)){
   close();opener?.focus({preventScroll:true});
  }
 });
 const answerToggle=doc.querySelector("[data-course-answer-toggle]");
 const answerPanel=doc.getElementById("course-inline-answer");
 if(answerToggle&&answerPanel)answerToggle.onclick=()=>{
  const show=answerPanel.hidden;
  if(show)close();
  answerPanel.hidden=!show;
  answerToggle.setAttribute("aria-expanded",String(show));
 };
 const reveal=doc.querySelector("[data-course-reveal]");
 if(reveal) reveal.onclick=()=>{
  const show=reveal.getAttribute("aria-pressed")!=="true";
  reveal.setAttribute("aria-pressed",String(show));
  body.toggleAttribute("data-course-revealed",show);
   doc.body.toggleAttribute("data-course-revealed",show);
 };
 doc.querySelectorAll(".course-media-entry :is(audio,video)").forEach((player,i,players)=>{
  courseBindCaptions(player,courseRemainingMedia(c)[i]);
  player.addEventListener("play",()=>players.forEach(other=>{if(other!==player)other.pause();}));
 });
}

function fitCourseProjection() {
 const host=document.getElementById("preview-size");
 if(!host)return;
 const wrap=host.parentElement;
 const inset=Number.parseFloat(getComputedStyle(wrap).paddingBottom)||0;
 const available=document.documentElement.clientHeight-wrap.getBoundingClientRect().top-window.scrollY-inset*2;
 const scale=Math.min(wrap.clientWidth/1280, Math.max(1,available)/720, maxProjectionScale);
 host.style.width=1280*scale+"px";
 host.style.height=720*scale+"px";
 document.getElementById("preview").style.transform="scale("+scale+")";
}

function courseHasPlacement(block) {
 if (block.answer?.mode && block.answer.mode!=="example") return true;
 if (block.rows?.some(row=>row.some(cell=>cell.answer))) return true;
 if (block.notes?.some(note=>note.answer)) return true;
 return block.fields?.some(field=>field.answer)||block.figures?.some(({item})=>item.answer?.mode&&item.answer.mode!=="example")||false;
}

function tidyCourseNavigation() {
 window.removeEventListener("resize",resize);
 resize=fitCourseProjection;
 window.addEventListener("resize",resize);
 resize();
 const style=document.createElement("style");
 style.textContent=".nav-step .dot,.nav-step:not(.flow-step) div>span{display:none}.nav-step:not(.flow-step){grid-template-columns:minmax(0,1fr)}";
 document.head.append(style);
}
if(typeof document!=="undefined"&&document.addEventListener)document.addEventListener("DOMContentLoaded",tidyCourseNavigation,{once:true});

